//! Read-only `isMiner(address)` against the TS-ABI fixture (CoNET-SI 215afb18, generated by
//! tests/fixtures/treasury_v3_gen/gen-isminer-fixtures.mjs with the pinned ethers 6.17.0).
//! In-process loopback stub only: no network, no vote, no signer.
mod common;

use alloy_primitives::Address;
use common::Answer;
use conet_node::chain::Rpc;
use conet_node::treasury_v3_miner::{decode_is_miner, encode_is_miner, is_miner};
use serde_json::{json, Value};
use std::sync::{Arc, Mutex};

const FIXTURE: &str = include_str!("fixtures/treasury_v3_isminer.json");
/// The address the stub is asked about. This test does not verify any deployment.
const TREASURY: &str = "0xa208982212978550594A7FEEB70a61665d129003";

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("fixture is JSON")
}

fn hex_bytes(s: &str) -> Vec<u8> {
    hex::decode(s.trim_start_matches("0x")).expect("fixture hex")
}

fn account(f: &Value, i: usize) -> Address {
    f["calls"][i]["account"]
        .as_str()
        .unwrap()
        .parse()
        .expect("checksummed fixture address")
}

#[test]
fn the_selector_matches_the_ethers_fixture() {
    let f = fixture();
    let want = f["selector"].as_str().unwrap();
    assert_eq!(want, "0x701b70ac");
    let got = format!("0x{}", hex::encode(&encode_is_miner(account(&f, 0))[..4]));
    assert_eq!(got, want);
}

#[test]
fn the_calldata_matches_the_fixture_for_every_account() {
    let f = fixture();
    for (i, call) in f["calls"].as_array().unwrap().iter().enumerate() {
        let got = format!("0x{}", hex::encode(encode_is_miner(account(&f, i))));
        assert_eq!(got, call["calldata"].as_str().unwrap(), "{}", call["name"]);
    }
}

#[test]
fn the_return_data_decodes_strictly_to_the_fixture_values() {
    let f = fixture();
    for case in f["returns"].as_array().unwrap() {
        let got = decode_is_miner(&hex_bytes(case["data"].as_str().unwrap()));
        let want = &case["expect"];
        if want.get("error").is_some() {
            assert!(
                got.is_err(),
                "{} must be an error, got {got:?}",
                case["name"]
            );
        } else {
            assert_eq!(
                got.unwrap(),
                want["value"].as_bool().unwrap(),
                "{}",
                case["name"]
            );
        }
    }
}

#[test]
fn an_empty_or_non_bool_answer_is_never_read_as_false() {
    assert!(decode_is_miner(&[]).is_err());
    assert!(decode_is_miner(&[0u8; 31]).is_err());
    assert!(decode_is_miner(&[0u8; 33]).is_err());
    let mut two = [0u8; 32];
    two[31] = 2;
    assert!(decode_is_miner(&two).is_err());
    assert!(!decode_is_miner(&[0u8; 32]).unwrap());
    let mut one = [0u8; 32];
    one[31] = 1;
    assert!(decode_is_miner(&one).unwrap());
}

/// Loopback node that answers every `eth_call` with `data`, and records the calls it receives.
async fn node_answering(data: &'static str, seen: Arc<Mutex<Vec<Value>>>) -> String {
    let answer: Answer = Arc::new(move |method: &str, params: &Value| {
        assert_eq!(method, "eth_call");
        seen.lock().unwrap().push(params.clone());
        json!(data)
    });
    common::serve(answer).await
}

#[tokio::test]
async fn the_stub_read_sends_the_fixture_calldata_to_the_treasury_and_returns_the_bool() {
    let f = fixture();
    let case = |name: &str| {
        f["returns"]
            .as_array()
            .unwrap()
            .iter()
            .find(|c| c["name"] == name)
            .unwrap()
            .clone()
    };
    for (name, want) in [("true", true), ("false", false)] {
        let data: &'static str = Box::leak(
            case(name)["data"]
                .as_str()
                .unwrap()
                .to_string()
                .into_boxed_str(),
        );
        let seen = Arc::new(Mutex::new(vec![]));
        let url = node_answering(data, seen.clone()).await;
        let rpc = Rpc::new(&url).unwrap();
        let who = account(&f, 1);
        assert_eq!(is_miner(&rpc, TREASURY, who).await.unwrap(), want, "{name}");
        let calls = seen.lock().unwrap();
        assert_eq!(calls.len(), 1);
        assert_eq!(
            calls[0][0]["to"].as_str().unwrap().to_ascii_lowercase(),
            TREASURY.to_ascii_lowercase()
        );
        assert_eq!(
            calls[0][0]["data"].as_str().unwrap(),
            format!("0x{}", hex::encode(encode_is_miner(who)))
        );
    }
}

#[tokio::test]
async fn the_stub_read_refuses_an_empty_or_non_bool_answer() {
    let f = fixture();
    for name in ["empty", "value_two", "short_31_bytes"] {
        let data: &'static str = Box::leak(
            f["returns"]
                .as_array()
                .unwrap()
                .iter()
                .find(|c| c["name"] == name)
                .unwrap()["data"]
                .as_str()
                .unwrap()
                .to_string()
                .into_boxed_str(),
        );
        let url = node_answering(data, Arc::new(Mutex::new(vec![]))).await;
        let rpc = Rpc::new(&url).unwrap();
        assert!(
            is_miner(&rpc, TREASURY, account(&f, 0)).await.is_err(),
            "{name}"
        );
    }
}
